// Command permgen generates internal/authz tables from the reviewed
// permission catalog (ADR-0007, ADR-0013). The catalog JSON stays the single
// source of truth; `make fmt-check` rejects a stale generated file.
//
// Usage: go run ./tools/permgen <catalog.json> <output.go>
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"os"
)

type catalog struct {
	Permissions []struct {
		ID             string `json:"id"`
		Kind           string `json:"kind"`
		Scope          string `json:"scope"`
		Administrative bool   `json:"administrative"`
		Sensitive      bool   `json:"sensitive"`
		OwnerOnly      bool   `json:"ownerOnly"`
	} `json:"permissions"`
	Roles []struct {
		ID     string            `json:"id"`
		Grants map[string]string `json:"grants"`
	} `json:"roles"`
	ProjectAccessLevels []struct {
		ID      string `json:"id"`
		MaxKind string `json:"maxKind"`
	} `json:"projectAccessLevels"`
}

var kinds = map[string]string{"read": "Read", "write": "Write"}
var scopes = map[string]string{"workspace": "WorkspaceScope", "project": "ProjectScope"}
var conditions = map[string]string{"all": "All", "own": "Own", "assigned": "Assigned"}

// Generate renders the Go source for a catalog.
func Generate(data []byte) ([]byte, error) {
	var c catalog
	if err := json.Unmarshal(data, &c); err != nil {
		return nil, fmt.Errorf("decode catalog: %w", err)
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by tools/permgen from docs/rbac/permission-catalog.json. DO NOT EDIT.\n\npackage authz\n\n")
	b.WriteString("var permissionTable = map[Permission]PermissionInfo{\n")
	for _, p := range c.Permissions {
		kind, ok1 := kinds[p.Kind]
		scope, ok2 := scopes[p.Scope]
		if !ok1 || !ok2 {
			return nil, fmt.Errorf("permission %s has unknown kind or scope", p.ID)
		}
		fmt.Fprintf(&b, "\t%q: {Kind: %s, Scope: %s, Administrative: %t, Sensitive: %t, OwnerOnly: %t},\n",
			p.ID, kind, scope, p.Administrative, p.Sensitive, p.OwnerOnly)
	}
	b.WriteString("}\n\nvar permissionOrder = []Permission{\n")
	for _, p := range c.Permissions {
		fmt.Fprintf(&b, "\t%q,\n", p.ID)
	}
	b.WriteString("}\n\nvar grantTable = map[Role]map[Permission]Condition{\n")
	for _, r := range c.Roles {
		fmt.Fprintf(&b, "\t%q: {\n", r.ID)
		for _, p := range c.Permissions {
			cond, ok := r.Grants[p.ID]
			if !ok {
				continue
			}
			name, known := conditions[cond]
			if !known {
				return nil, fmt.Errorf("role %s grants %s with unknown condition %s", r.ID, p.ID, cond)
			}
			fmt.Fprintf(&b, "\t\t%q: %s,\n", p.ID, name)
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n\nvar accessLevelTable = map[AccessLevel]Kind{\n")
	for _, l := range c.ProjectAccessLevels {
		kind, ok := kinds[l.MaxKind]
		if !ok {
			return nil, fmt.Errorf("access level %s has unknown maxKind", l.ID)
		}
		fmt.Fprintf(&b, "\t%q: %s,\n", l.ID, kind)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

func main() {
	if len(os.Args) != 3 {
		fmt.Fprintln(os.Stderr, "usage: permgen <catalog.json> <output.go>")
		os.Exit(2)
	}
	data, err := os.ReadFile(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, "permgen:", err)
		os.Exit(1)
	}
	out, err := Generate(data)
	if err != nil {
		fmt.Fprintln(os.Stderr, "permgen:", err)
		os.Exit(1)
	}
	if err := os.WriteFile(os.Args[2], out, 0o644); err != nil { //nolint:gosec // G306: generated source file
		fmt.Fprintln(os.Stderr, "permgen:", err)
		os.Exit(1)
	}
}
